```sql
-- 1. Subir notas inferiores a 5 en Convocatoria 1
UPDATE notas
SET nota = nota + 0.5
WHERE convocatoria = 'Convocatoria 1' AND nota < 5;

-- 2. Email a NULL de alumnos inactivos
UPDATE alumnos
SET email = NULL
WHERE activo = FALSE;

-- 3. Eliminar notas del alumno 3
DELETE FROM notas WHERE id_alumno = 3;

-- 4. Eliminar productos con stock 0
DELETE FROM productos WHERE stock = 0;
```

